insert into public.exercises (id, category, title, summary, steps, duration_min, levels, positions, payload) values
('tac-counter-width', 'tactics', 'Қарсы шабуылда кеңдік беру', 'Допты қайтарып алған сәтте қапталшылар алаңды кеңейтіп, қорғанысты созуы керек.', '["Схемаға қараңыз: 6-нөмір допты орталықта қайтарып алды.","Қарсыластың қорғанысы әлі ретке келмеген — бұл 3–5 секундтық мүмкіндік.","Сұраққа жауап беріңіз, содан кейін түсіндірмені оқыңыз."]'::jsonb, 8, '{beginner,intermediate,advanced}'::public.level[], null, '{"players":[{"n":6,"t":"a","x":34,"y":62},{"n":7,"t":"a","x":60,"y":58,"hl":true},{"n":9,"t":"a","x":34,"y":46},{"n":11,"t":"a","x":8,"y":57},{"n":8,"t":"a","x":22,"y":70},{"n":4,"t":"b","x":14,"y":36},{"n":5,"t":"b","x":28,"y":33},{"n":3,"t":"b","x":41,"y":33},{"n":2,"t":"b","x":54,"y":38},{"n":8,"t":"b","x":26,"y":54},{"n":6,"t":"b","x":44,"y":55}],"ball":{"x":36,"y":60},"arrows":[{"x1":60,"y1":58,"x2":63,"y2":28,"k":"run"},{"x1":34,"y1":46,"x2":30,"y2":30,"k":"run"},{"x1":34,"y1":62,"x2":61,"y2":31,"k":"pass"}],"quiz":{"question":"Біз допты орталықта қайтарып алдық. 7-нөмірлі қапталшы не істеуі керек?","options":["Допқа жақындап, қысқа пас сұрау","Қаптал бойымен алға, бос кеңістікке жүгіру","Орнында тұрып, қорғанысқа көмектесу"],"answer":1,"explain":"Қарсы шабуылда кеңдік пен тереңдік шешеді. Қапталшы алға жүгірсе, қарсылас қорғаушысы оны қуалауға мәжбүр болады — орталықта 9-нөмірге кеңістік ашылады. Допқа жақындау қарсыласқа қайта жиналуға уақыт береді."}}'::jsonb),
('tac-triangles', 'tactics', 'Үшбұрыш: пас нұсқаларын құру', 'Доп иесінің кемінде екі пас нұсқасы болуы үшін ойыншылар қиғаш бұрышта тұрады.', '["Сол жақ қорғаушыда (3) доп, қапталда қысым бар.","Бір сызықта тұрған ойыншыға пасты қарсылас оңай кеседі.","8-нөмір қайда тұрса, ең жақсы нұсқа болады?"]'::jsonb, 8, '{beginner,intermediate,advanced}'::public.level[], null, '{"players":[{"n":3,"t":"a","x":8,"y":66},{"n":11,"t":"a","x":6,"y":46},{"n":8,"t":"a","x":26,"y":64,"hl":true},{"n":4,"t":"a","x":24,"y":84},{"n":7,"t":"b","x":13,"y":60},{"n":2,"t":"b","x":10,"y":44},{"n":10,"t":"b","x":26,"y":50}],"ball":{"x":10,"y":64},"arrows":[{"x1":26,"y1":64,"x2":20,"y2":55,"k":"run"},{"x1":9,"y1":65,"x2":19,"y2":56,"k":"pass"}],"quiz":{"question":"3-нөмірлі қорғаушыда доп. 8-нөмірлі жартылай қорғаушы қайда тұруы керек?","options":["3-нөмірдің дәл жанына, бір сызыққа","Қиғаш бұрышта, қарсыластардың арасындағы бос аймаққа","Қарсы қапталға, алысқа"],"answer":1,"explain":"3, 8 және 11 үшбұрыш құрағанда доп иесінің екі пас нұсқасы болады. Қарсыластар арасындағы аймаққа келген 8-нөмір допты алып, бірден алға бұрыла алады. Бір сызықта тұру — бір пас жолы, оны кесу оңай."}}'::jsonb),
('tac-press-trap', 'tactics', 'Прессинг: допты қапталға итеру', 'Шабуылшы қисық жүгіріспен орталыққа пас жолын жауып, қарсыласты бүйір сызыққа қамайды.', '["Қарсыластың оң қорғаушысы қапталда допты алды.","Бүйір сызық — «қосымша қорғаушы»: ол жаққа доптың шығатын жолы аз.","Команда бірге жылжиды: бір ойыншы қысады, қалғандары жақын нұсқаларды жабады."]'::jsonb, 10, '{intermediate,advanced}'::public.level[], null, '{"players":[{"n":9,"t":"a","x":40,"y":20,"hl":true},{"n":7,"t":"a","x":54,"y":42},{"n":8,"t":"a","x":42,"y":44},{"n":10,"t":"a","x":30,"y":36},{"n":2,"t":"b","x":60,"y":26},{"n":5,"t":"b","x":40,"y":12},{"n":6,"t":"b","x":44,"y":32},{"n":7,"t":"b","x":62,"y":44}],"ball":{"x":61,"y":24},"arrows":[{"x1":40,"y1":20,"x2":54,"y2":22,"k":"run","curve":-8},{"x1":54,"y1":42,"x2":61,"y2":36,"k":"run"},{"x1":42,"y1":44,"x2":46,"y2":35,"k":"run"}],"quiz":{"question":"Қарсылас қорғаушысы қапталда допты алды. 9-нөмірлі шабуылшы қалай прессинг жасайды?","options":["Тура допқа қарай жүгіреді","Қисық жүгіріспен орталыққа пас жолын жауып, допты қапталға итереді","Орнында тұрып, күтеді"],"answer":1,"explain":"Тура жүгірсе, қарсылас допты орталыққа (5-нөмірге) оңай береді. Қисық жүгіріс сол пас жолын «көлеңкесімен» жабады. Доп қапталда қалады, 7 және 8 жақын нұсқаларды жауып, допты қайтарып алуға мүмкіндік туады."}}'::jsonb),
('tac-line-step-up', 'tactics', 'Қорғаныс сызығын көтеру', 'Қарсылас допты артқа ойнағанда қорғаныс бірге алға шығып, кеңістікті тарылтады.', '["Қарсылас шабуылшысы допты артқа, өз жартылай қорғаушысына берді.","Доп иесіне қысым жоқ болса — артқа шегіну, қысым бар болса — алға шығу.","Төрт қорғаушы бір сызықта қозғалуы керек."]'::jsonb, 8, '{beginner,intermediate,advanced}'::public.level[], null, '{"players":[{"n":3,"t":"a","x":12,"y":82},{"n":4,"t":"a","x":27,"y":84,"hl":true},{"n":5,"t":"a","x":41,"y":84},{"n":2,"t":"a","x":56,"y":82},{"n":8,"t":"a","x":34,"y":62},{"n":9,"t":"b","x":32,"y":74},{"n":11,"t":"b","x":50,"y":72},{"n":8,"t":"b","x":30,"y":58}],"ball":{"x":32,"y":71},"arrows":[{"x1":32,"y1":72,"x2":30,"y2":60,"k":"pass"},{"x1":12,"y1":82,"x2":12,"y2":74,"k":"run"},{"x1":27,"y1":84,"x2":27,"y2":76,"k":"run"},{"x1":41,"y1":84,"x2":41,"y2":76,"k":"run"},{"x1":56,"y1":82,"x2":56,"y2":74,"k":"run"},{"x1":34,"y1":62,"x2":31,"y2":59,"k":"run"}],"quiz":{"question":"Қарсылас допты артқа ойнады, 8-нөмір доп иесін қысып жатыр. Қорғаныс сызығы не істейді?","options":["Бірге алға шығып, сызықты көтереді","Артқа, өз қақпасына шегінеді","Әр қорғаушы өз ойыншысын қуалайды"],"answer":0,"explain":"Доп артқа кеткенде және доп иесіне қысым болғанда, ұзын пас қаупі аз. Сызықты бірге көтеру шабуылшыларды офсайдқа қалдырады және командалар арасындағы аралықты қысқартады. Бір қорғаушы артта қалса — бүкіл сызық бұзылады."}}'::jsonb),
('tac-third-man', 'tactics', 'Үшінші адамның жүгірісі', 'A → B → C: допсыз жүгірген үшінші ойыншыға бір жанасумен пас беру.', '["6-нөмір допты төмен түскен 9-нөмірге береді.","9-нөмірдің артында қорғаушы тұр — ол бұрыла алмайды.","Бұл сәтте 8-нөмір қорғаушылардың арасына жүгіреді."]'::jsonb, 10, '{intermediate,advanced}'::public.level[], null, '{"players":[{"n":6,"t":"a","x":30,"y":72},{"n":9,"t":"a","x":34,"y":55,"hl":true},{"n":8,"t":"a","x":44,"y":64},{"n":11,"t":"a","x":10,"y":52},{"n":5,"t":"b","x":34,"y":49},{"n":6,"t":"b","x":24,"y":58},{"n":8,"t":"b","x":46,"y":56},{"n":4,"t":"b","x":26,"y":38},{"n":3,"t":"b","x":42,"y":38}],"ball":{"x":31,"y":70},"arrows":[{"x1":30,"y1":71,"x2":34,"y2":57,"k":"pass"},{"x1":44,"y1":64,"x2":48,"y2":36,"k":"run","curve":4},{"x1":35,"y1":55,"x2":47,"y2":40,"k":"pass"}],"quiz":{"question":"6-нөмір 9-ға пас берді. Ең қауіпті келесі әрекет қандай?","options":["9 допты ұстап, бұрылуға тырысады","9 бір жанасумен алға жүгірген 8-ге береді","9 допты 6-ға қайтарады"],"answer":1,"explain":"Артында қорғаушы тұрғанда 9-нөмірдің бұрылуы қиын. Бірақ қорғаушылар 9-ға назар аударған сәтте 8-нөмірдің жүгірісін ешкім бақыламайды. Бір жанасулы пас — қорғаныс сызығын бұзудың ең жылдам жолы."}}'::jsonb),
('tac-counter-press', 'tactics', 'Допты жоғалтқаннан кейінгі 5 секунд', 'Контрпрессинг: ең жақын ойыншылар бірден доп иесіне шабуыл жасап, пас жолдарын жабады.', '["Біз шабуылда допты жоғалттық.","Қарсылас әлі басын көтеріп үлгермеді — ол ең осал сәт.","Кім қысады, кім пас жолдарын жабады?"]'::jsonb, 8, '{beginner,intermediate,advanced}'::public.level[], null, '{"players":[{"n":10,"t":"a","x":46,"y":44,"hl":true},{"n":8,"t":"a","x":32,"y":48},{"n":9,"t":"a","x":40,"y":30},{"n":7,"t":"a","x":58,"y":34},{"n":6,"t":"b","x":41,"y":41},{"n":8,"t":"b","x":26,"y":40},{"n":10,"t":"b","x":52,"y":54},{"n":4,"t":"b","x":34,"y":24}],"ball":{"x":41,"y":43},"arrows":[{"x1":46,"y1":44,"x2":43,"y2":42,"k":"run"},{"x1":32,"y1":48,"x2":34,"y2":42,"k":"run"},{"x1":40,"y1":30,"x2":38,"y2":37,"k":"run"},{"x1":58,"y1":34,"x2":52,"y2":47,"k":"run"}],"quiz":{"question":"Біз допты жоғалттық. Алғашқы 5 секундта не істейміз?","options":["Бәріміз бірден өз жартымызға қайтамыз","Ең жақын 3 ойыншы доп иесін қысып, қалғандары пас жолдарын жабады","Тек шабуылшы прессинг жасайды"],"answer":1,"explain":"Доп жаңа ғана ауысқанда қарсылас ұйымдаспаған, ал біздің ойыншылар допқа жақын. Тез әрі бірге қысса, допты қарсылас қақпасына жақын жерде қайтарып алуға болады. 5 секундта шықпаса — тез артқа оралып, қорғанысқа тұрамыз."}}'::jsonb),
('phy-sprints', 'physical', 'Жарылғыш спринттер 10 × 20 м', 'Қысқа, максималды жылдамдықтағы жүгірістер — футболдағы ең маңызды жылдамдық сапасы.', '["Қыздыру: 5 минут жеңіл жүгіру, тізені жоғары көтеру, артқа сермеу.","20 метрді өлшеп, екі конус қойыңыз.","Әр спринтті максималды жылдамдықпен жүгіріңіз, кері қарай жаяу қайтыңыз.","Спринттер арасында толық демалыңыз — сапа саннан маңызды."]'::jsonb, 15, '{beginner,intermediate,advanced}'::public.level[], null, '{"sets":10,"reps":"20 м","rest_sec":45,"tip":"Алғашқы 3 қадам қысқа әрі қуатты, дене алға еңкейген."}'::jsonb),
('phy-agility', 'physical', 'Конустармен ептілік (зигзаг)', 'Бағытты тез өзгерту — қорғаушыдан өту және қарсыласты ұстау үшін керек.', '["6 конусты зигзаг түрінде, бір-бірінен 3 метр қашықтықта қойыңыз.","Әр конуста аяқтың сыртқы жағымен итеріліп, бағытты өзгертіңіз.","Дене салмағы төмен, тізе бүгілген, басыңыз көтерулі."]'::jsonb, 12, '{beginner,intermediate,advanced}'::public.level[], null, '{"sets":6,"reps":"1 айналым","rest_sec":40,"tip":"Бұрылыста аяқты кең қойып, жамбаспен итеріліңіз."}'::jsonb),
('phy-plyo', 'physical', 'Плиометрика: секіру күші', 'Секірулер аяқтың жарылғыш күшін дамытады — басқа ойнау мен спринт үшін.', '["Орнында жоғары секіру — 8 рет, жұмсақ қону.","Бір аяқпен бүйірге секіру — әр аяққа 6 рет.","Ұзындыққа секіру — 5 рет, екі аяқпен қону.","Қону кезінде тізе ішке бұрылмауы керек."]'::jsonb, 12, '{intermediate,advanced}'::public.level[], null, '{"sets":3,"reps":"1 айналым","rest_sec":90,"tip":"Сапа маңызды: әр секіру толық күшпен, шаршасаңыз тоқтаңыз."}'::jsonb),
('phy-core', 'physical', 'Кор: тұрақтылық циклі', 'Күшті дене ортасы тепе-теңдікті, соққы күшін және жарақаттан қорғанысты арттырады.', '["Планка — 30 секунд.","Бүйірлік планка — әр жаққа 20 секунд.","«Өлі қоңыз» (dead bug) — 10 рет.","Көпір (glute bridge) — 12 рет."]'::jsonb, 10, '{beginner,intermediate,advanced}'::public.level[], null, '{"sets":3,"reps":"1 цикл","rest_sec":45,"tip":"Белді доғаламаңыз, іш бұлшықетін үнемі қысулы ұстаңыз."}'::jsonb),
('phy-intervals', 'physical', 'Төзімділік: 4 × 4 минут интервал', 'Матчтың соңына дейін жоғары қарқынды сақтауға көмектесетін аэробты жаттығу.', '["Қыздыру: 5 минут жеңіл жүгіру.","4 минут жылдам жүгіру — сөйлеу қиын болатындай қарқын.","3 минут белсенді демалыс — жаяу немесе өте баяу жүгіру.","Барлығы 4 рет қайталаңыз."]'::jsonb, 25, '{intermediate,advanced}'::public.level[], null, '{"sets":4,"reps":"4 мин","rest_sec":180,"work_sec":240,"tip":"Қарқын әр интервалда бірдей болсын — бірінші интервалда бар күшті жұмсамаңыз."}'::jsonb),
('phy-injury-prevention', 'physical', 'Жарақаттың алдын алу', 'Сан артқы бұлшықеті мен тобық үшін қарапайым жаттығулар — жарақат қаупін азайтады.', '["Бір аяқта тепе-теңдік — көзді жұмып, әр аяққа 30 секунд.","Бір аяқпен жамбас бүгу (single-leg RDL) — әр аяққа 8 рет.","Бүйірге жүру (lateral walk) — әр жаққа 10 қадам.","Өкшені көтеру — 15 рет."]'::jsonb, 10, '{beginner,intermediate,advanced}'::public.level[], null, '{"sets":2,"reps":"1 цикл","rest_sec":30,"tip":"Апта сайын 2–3 рет жасасаңыз, нәтижесі жақсы болады."}'::jsonb),
('men-box-breathing', 'mental', 'Шаршы тыныс: толқуды басу', 'Ойын алдында немесе пенальти алдында жүйкені тыныштандыратын 4-4-4-4 тынысы.', '["4 секунд мұрынмен дем алыңыз.","4 секунд тынысты ұстаңыз.","4 секунд аузыңызбен баяу дем шығарыңыз.","4 секунд тынысты ұстаңыз. 6 рет қайталаңыз."]'::jsonb, 4, '{beginner,intermediate,advanced}'::public.level[], null, '{"breath":[4,4,4,4],"rounds":6,"tip":"Матч алдындағы шешуші сәтте 2–3 цикл жеткілікті."}'::jsonb),
('men-visualization', 'mental', 'Визуализация: сәтті ойын', 'Ми елестетілген әрекетті шынайы жаттығу сияқты қабылдайды — сенімділік артады.', '["Ыңғайлы отырып, көзіңізді жұмыңыз.","Стадионды, шөптің иісін, жанкүйерлердің дауысын елестетіңіз.","Өзіңіздің 3 сәтті әрекетіңізді егжей-тегжейлі көріңіз: дәл пас, жақсы қабылдау, гол.","Әр әрекеттен кейінгі сезімді сезініңіз."]'::jsonb, 6, '{beginner,intermediate,advanced}'::public.level[], null, '{"journal":"Бүгін қандай 3 сәтті әрекетті елестеттіңіз?","tip":"Ұйықтар алдында немесе матч күні таңертең жасаңыз."}'::jsonb),
('men-reset', 'mental', 'Қателіктен кейін «қайта жүктеу»', 'Үздік ойыншылар да қателеседі. Олардың айырмашылығы — келесі әрекетке тез оралу.', '["Өзіңіздің «қайта жүктеу» әрекетіңізді таңдаңыз: қолғапты түзету, шортыңызды сипау, терең дем алу.","Бір кодтық сөз таңдаңыз: «Келесі!», «Алға!» т.б.","Соңғы ойыныңыздағы бір қателікті еске түсіріп, ритуалды жасап көріңіз.","Жаттығуда әр қателіктен кейін осы ритуалды қолданыңыз."]'::jsonb, 5, '{beginner,intermediate,advanced}'::public.level[], null, '{"journal":"Сіздің «қайта жүктеу» әрекетіңіз және кодтық сөзіңіз қандай?","tip":"Қателікті матчтан кейін талдаңыз, матч кезінде емес."}'::jsonb),
('men-goals', 'mental', 'Апталық мақсат қою', 'Нақты, өлшенетін мақсат мотивацияны арттырады және прогресті көрсетеді.', '["Нәтиже мақсаты емес, әрекет мақсатын таңдаңыз: «гол соғу» емес, «күнде 50 соққы жасау».","Мақсат нақты, өлшенетін және орындалатын болсын.","Оны жазып, көрінетін жерге іліңіз."]'::jsonb, 5, '{beginner,intermediate,advanced}'::public.level[], null, '{"journal":"Осы аптадағы бір нақты мақсатыңыз қандай?","tip":"Апта соңында мақсатыңызға қайта оралып, бағалаңыз."}'::jsonb),
('men-self-talk', 'mental', 'Өзіңмен позитивті сөйлесу', 'Ішкі дауыс ойынға әсер етеді. Сынайтын сөздерді нұсқау беретін сөздерге ауыстырыңыз.', '["Ойында өзіңізге жиі айтатын 2 жағымсыз сөзді жазыңыз (мысалы, «Мен әлсізбін»).","Әрқайсысын нұсқау беретін сөзге ауыстырыңыз: «Денені ашып, допты қабылда».","Бүгінгі жаттығуда осы жаңа сөздерді қолданыңыз."]'::jsonb, 5, '{beginner,intermediate,advanced}'::public.level[], null, '{"journal":"Қандай сөзді қандай сөзге ауыстырдыңыз?","tip":"Сөз қысқа, нақты және қазіргі шақта болсын."}'::jsonb),
('men-review', 'mental', 'Жаттығудан кейінгі талдау', 'Күнделік жүргізу — өз ойыныңды түсінудің ең қарапайым жолы.', '["Бүгін жақсы шыққан 2 нәрсені жазыңыз.","Жақсартуға болатын 1 нәрсені жазыңыз.","Ертеңге бір нақты қадам белгілеңіз."]'::jsonb, 5, '{beginner,intermediate,advanced}'::public.level[], null, '{"journal":"2 жақсы нәрсе, 1 жақсартатын нәрсе, ертеңгі қадам:","tip":"Өзіңізге жаттықтырушыдай қараңыз — әділ, бірақ мейірімді."}'::jsonb),
('tec-wall-pass', 'technique', 'Қабырғамен екі аяқпен пас', 'Ең қарапайым әрі тиімді жаттығу: дәл пас және бірінші жанасу.', '["Қабырғадан 3–5 метр қашықтықта тұрыңыз.","Оң аяқтың ішкі бетімен пас — сол аяқпен қабылдау. Содан кейін керісінше.","Әр 30 пастан кейін қашықтықты 1 метрге ұлғайтыңыз.","Деңгей жоғары болса — бір жанасумен ойнаңыз."]'::jsonb, 10, '{beginner,intermediate,advanced}'::public.level[], null, '{"sets":4,"reps":"30 пас","rest_sec":30,"tip":"Тірек аяқ доптың жанында, тобық қатты бекітілген."}'::jsonb),
('tec-juggling', 'technique', 'Жонглинг: доппен сезім', 'Допты жерге түсірмей ұстау — доп сезімі мен үйлесімділікті дамытады.', '["Бастауыш: доп жерден бір рет секіргеннен кейін соғыңыз.","Тек оң аяқпен, тек сол аяқпен, содан кейін кезекпен.","Жеке рекордыңызды жазып отырыңыз.","Жоғары деңгей: аяқ — сан — бас тізбегі."]'::jsonb, 10, '{beginner,intermediate,advanced}'::public.level[], null, '{"sets":5,"reps":"2 мин","rest_sec":30,"tip":"Аяқтың ұшы сәл көтерулі, доп айналмауы керек."}'::jsonb),
('tec-dribble-cones', 'technique', 'Конустар арасымен доп жүргізу', 'Тығыз кеңістікте допты жақын ұстау және аяқтың әр бетін қолдану.', '["6 конусты бір сызықта 1 метр қашықтықта қойыңыз.","Тек оң аяқпен (ішкі және сыртқы бет), содан кейін тек сол аяқпен өтіңіз.","Табанмен тартып жүргізу нұсқасы.","Басыңызды көтеріп, допқа аз қарауға тырысыңыз."]'::jsonb, 12, '{beginner,intermediate,advanced}'::public.level[], null, '{"sets":6,"reps":"1 өту","rest_sec":30,"tip":"Жылдамдықты техника тұрақты болғанда ғана арттырыңыз."}'::jsonb),
('tec-open-body', 'technique', 'Ашық денемен қабылдау', 'Допты алыс аяқпен қабылдау ойынды алға қарай жалғастыруға мүмкіндік береді.', '["Серіктес немесе қабырға пас береді.","Денені жарты бұрылыста ұстап, допты алыс (артқы) аяқпен қабылдаңыз.","Бір жанасумен бағыт өзгертіп, екінші жанасумен пас беріңіз.","Пас алар алдында иық үстінен қараңыз (сканерлеу)."]'::jsonb, 10, '{intermediate,advanced}'::public.level[], null, '{"sets":4,"reps":"20 қабылдау","rest_sec":30,"tip":"Доп келмей тұрып ақпарат жинаңыз: кім қайда тұр?"}'::jsonb),
('tec-shooting', 'technique', 'Соққы: дәлдік бірінші', 'Қақпаның бұрыштарына аяқтың ішкі бетімен дәл соққы — гол соғудың ең сенімді жолы.', '["Қақпаның төменгі екі бұрышына нысана (конус, футболка) қойыңыз.","Айып алаңының шетінен аяқтың ішкі бетімен 10 соққы — дәлдікке.","Содан кейін көтерумен (шнурокпен) 10 соққы.","Әр нысанаға тигенін санап, жазып отырыңыз."]'::jsonb, 15, '{beginner,intermediate,advanced}'::public.level[], null, '{"sets":2,"reps":"10 соққы","rest_sec":60,"tip":"Соққы кезінде дене доптың үстінде, тірек аяқ нысанаға қарайды."}'::jsonb),
('tec-gk-handling', 'technique', 'Қақпашы: допты қауіпсіз ұстау', '«W» ұстау техникасы және бүйірге құлау — қақпашының негізі.', '["Кеуде деңгейіндегі доп: саусақтар «W» пішінінде, бас бармақтар бір-біріне жақын.","Төмен доп: аяқтарды жақын қойып, допты кеудеге «орап» алыңыз.","Бүйірге құлау: аяқтың бүйірі — жамбас — иық тізбегімен.","Серіктес 20 доп лақтырады, әрқайсысын жерге түсірмей ұстаңыз."]'::jsonb, 12, '{beginner,intermediate,advanced}'::public.level[], '{gk}'::text[], '{"sets":3,"reps":"20 доп","rest_sec":45,"tip":"Көз доптан ұсталғанға дейін айрылмайды."}'::jsonb),
('phy-gk-reflex', 'physical', 'Қақпашы: реакция және секіру', 'Жылдам аяқ жұмысы мен жарылғыш секіру — қиын соққыларды қайтару үшін.', '["Бүйірге жылжу (shuffle): штангадан штангаға 6 рет, денені қақпаға параллель ұстаңыз.","Серіктес допты қабырғаға тебеді, сіз секіргенде шыққан допты ұстайсыз — 10 рет.","Тізерлеп тұрып, бүйірге құлап, тез тұру — әр жаққа 6 рет.","Бір аяқпен итеріліп, жоғары доп ұстау — әр аяққа 5 рет."]'::jsonb, 12, '{beginner,intermediate,advanced}'::public.level[], '{gk}'::text[], '{"sets":3,"reps":"1 цикл","rest_sec":60,"tip":"Салмақ алдыңғы табанда, тізе бүгулі — кез келген бағытқа дайын бол."}'::jsonb),
('tec-def-heading', 'technique', 'Қорғаушы: басымен ойнау', 'Допты жоғары, алысқа және қапталға шығару — орталық қорғаушының негізгі қаруы.', '["Серіктес допты қолмен лақтырады. Маңдаймен соғыңыз, көзіңізді жұммаңыз.","Мойын мен денені артқа тартып, алға «қамшыдай» сілтеңіз.","Допты жоғары әрі алысқа шығарыңыз — 15 рет.","Секіріп, ең биік нүктеде соғу — 10 рет."]'::jsonb, 12, '{beginner,intermediate,advanced}'::public.level[], '{def}'::text[], '{"sets":3,"reps":"15 соққы","rest_sec":45,"tip":"Жасөспірімдерге басымен ойнауды жеңіл доппен және аз санмен жаттықтырған дұрыс."}'::jsonb),
('phy-def-backpedal', 'physical', 'Қорғаушы: артқа жүгіру және бұрылу', 'Шабуылшыға қарап шегіну және жамбасты тез бұрып, артынан қуу.', '["5 метр артқа жүгіру (backpedal), қадамдар қысқа, дене алға еңкейген.","Сигнал бойынша жамбасты 45° бұрып, 10 метр спринт.","Бүйірлей жылжу (side shuffle) — 5 метр, сосын алға спринт.","Әр қайталауда бұрылу жағын ауыстырыңыз."]'::jsonb, 12, '{beginner,intermediate,advanced}'::public.level[], '{def}'::text[], '{"sets":6,"reps":"1 айналым","rest_sec":40,"tip":"Аяқтарды айқастырмаңыз — тепе-теңдік жоғалады."}'::jsonb),
('tec-mid-scan', 'technique', 'Жартылай қорғаушы: сканерлеу және бір жанасу', 'Доп келмей тұрып айналаға қарау және бірінші жанасумен ойынды жалғастыру.', '["Ортада тұрыңыз, екі жағыңызда 2 серіктес (немесе 2 қабырға/конус).","Пас келмей тұрып иық үстінен екі рет қараңыз.","Серіктес түсін немесе санын айқайлайды — соған қарай бұрылып пас беріңіз.","Деңгей жоғары болса — тек бір жанасумен."]'::jsonb, 12, '{beginner,intermediate,advanced}'::public.level[], '{mid}'::text[], '{"sets":4,"reps":"20 пас","rest_sec":30,"tip":"Үздік жартылай қорғаушылар доп алар алдындағы 10 секундта бірнеше рет айналаға қарайды."}'::jsonb),
('phy-mid-repeat', 'physical', 'Жартылай қорғаушы: box-to-box спринттер', 'Қайталанатын спринттер — матч бойы шабуыл мен қорғанысқа үлгеру үшін.', '["30 метр спринт, 30 метр жеңіл жүгіріп қайту — бұл бір қайталау.","6 қайталау қатарынан, үзіліссіз.","Сериялар арасында 2 минут демалыс."]'::jsonb, 15, '{intermediate,advanced}'::public.level[], '{mid}'::text[], '{"sets":3,"reps":"6 × 30 м","rest_sec":120,"tip":"Соңғы спринт біріншісінен көп баяу болмауы керек — қарқынды дұрыс бөл."}'::jsonb),
('tec-fwd-finishing', 'technique', 'Шабуылшы: бір жанасумен соғу', 'Айып алаңында уақыт аз — допты тоқтатпай, бірден дәл соғу.', '["Серіктес жерден пас береді, сіз бір жанасумен бұрышқа соғасыз — 10 рет.","Пас бүйірден келеді: жақын штангаға кесіп кіріп соғу — 10 рет.","Әуеден келген доп: волей немесе басымен — 10 рет.","Әр соққыдан кейін келесіге тез қайту."]'::jsonb, 15, '{beginner,intermediate,advanced}'::public.level[], '{fwd}'::text[], '{"sets":3,"reps":"10 соққы","rest_sec":60,"tip":"Күштен бұрын дәлдік: төменгі бұрыштарға соғылған доп жиі гол болады."}'::jsonb),
('phy-fwd-acceleration', 'physical', 'Шабуылшы: орнынан жылдам старт', 'Қорғаушыдан бірінші 5 метрде озу — шабуылшының басты артықшылығы.', '["Жартылай бұрылып тұрып, сигнал бойынша 10 метр спринт — 6 рет.","Артқа 2 қадам жасап, бірден алға 10 метр спринт (жалған қозғалыс) — 6 рет.","Отырған күйден тұрып, 5 метр спринт — 4 рет."]'::jsonb, 12, '{beginner,intermediate,advanced}'::public.level[], '{fwd}'::text[], '{"sets":2,"reps":"1 цикл","rest_sec":60,"tip":"Алғашқы қадамдар қысқа, қолдар белсенді жұмыс істейді."}'::jsonb)
